<?php defined('_JEXEC') or die; use Joomla\CMS\HTML\HTMLHelper; use Joomla\CMS\Language\Text; use Joomla\CMS\Router\Route; $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<form action="<?= Route::_('index.php?option=com_decaroevents&view=registrations') ?>" method="post" id="adminForm" name="adminForm"><div class="xdecaro-scope"><div class="xdecaro-table-wrap"><table class="xdecaro-table"><thead><tr><th><?= HTMLHelper::_('grid.checkall') ?></th><th><?= Text::_('COM_DECAROEVENTS_EVENT') ?></th><th><?= Text::_('COM_DECAROEVENTS_FIELD_NAME') ?></th><th><?= Text::_('JGLOBAL_EMAIL') ?></th><th><?= Text::_('JSTATUS') ?></th><th><?= Text::_('COM_DECAROEVENTS_FIELD_CHECKED_IN') ?></th></tr></thead><tbody><?php foreach($this->items as $i=>$item):?><tr><td><?= HTMLHelper::_('grid.id',$i,(int)$item->id) ?></td><td><?= $e($item->event_title) ?></td><td><a href="<?= Route::_('index.php?option=com_decaroevents&task=registration.edit&id='.(int)$item->id) ?>"><?= $e($item->name) ?></a></td><td><?= $e($item->email) ?></td><td><span class="xdecaro-badge <?= $item->status==='confirmed'?'xdecaro-badge--success':($item->status==='waitlist'?'xdecaro-badge--warning':'') ?>"><?= Text::_('COM_DECAROEVENTS_STATUS_'.strtoupper($item->status)) ?></span></td><td><?= $e($item->checked_in_at ?: '—') ?></td></tr><?php endforeach;?></tbody></table></div><?= $this->pagination->getListFooter() ?></div><input type="hidden" name="task" value=""><input type="hidden" name="boxchecked" value="0"><?= HTMLHelper::_('form.token') ?></form>
